import './ChipBar.css';
import { BookStatus } from '../../types';

interface ChipBarProps {
  statuses: BookStatus[];
  selected: Set<BookStatus>;
  onSelectionChange: (updated: Set<BookStatus>) => void;
}

const STATUS_LABEL: Record<BookStatus, string> = {
  'want-to-read': 'Want to read',
  reading: 'Reading',
  read: 'Read',
};

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleChipClick(status: BookStatus): void {
    const updated = new Set(selected);
    if (updated.has(status)) {
      updated.delete(status);
    } else {
      updated.add(status);
    }
    onSelectionChange(updated);
  }

  return (
    <div className="chip-bar" role="group" aria-label="Filter by status">
      {statuses.map((status) => {
        const pressed = selected.has(status);
        return (
          <button
            key={status}
            type="button"
            className="chip-bar-chip"
            aria-pressed={pressed}
            onClick={() => handleChipClick(status)}
          >
            {STATUS_LABEL[status]}
          </button>
        );
      })}
    </div>
  );
}
